/* Educational explanations only. Does not read or modify financial records. */
(()=>{'use strict';
const definitions={
 plan:['Calcula cuánto queda para las deudas después de ingresos, gastos y pagos mínimos. Registra cada gasto una sola vez.','Calculate what remains for debts after income, expenses and minimum payments. Enter each expense only once.'],
 income:['Ingresos que recibes al mes, después de impuestos y descuentos. Usa la misma moneda que en los demás campos.','Your monthly take-home income after taxes and deductions. Use the same currency for all fields.'],
 essential:['Gastos esenciales del mes, como vivienda, alimentos y servicios básicos. No los repitas en gastos fijos o variables.','Essential monthly expenses such as housing, food and utilities. Do not repeat them under fixed or variable expenses.'],
 fixed:['Otros gastos que suelen ser iguales cada mes y que no incluiste como esenciales.','Other expenses that are usually the same each month and are not already included as essential.'],
 variable:['Otros gastos que cambian de un mes a otro y que no incluiste en otra categoría.','Other expenses that vary from month to month and are not included in another category.'],
 minimums:['Suma de los pagos mínimos mensuales exigidos por tus entidades. Pagar solo el mínimo no necesariamente evita intereses.','Total monthly minimum payments required by lenders. Paying only the minimum does not necessarily avoid interest.'],
 extra:['Dinero adicional que propones abonar cada mes después de cubrir gastos y pagos mínimos.','Additional amount you propose paying each month after covering expenses and minimum payments.'],
 scenarioIncome:['Prueba cuánto cambiaría tu capacidad si recibieras ingresos mensuales adicionales; no modifica tu presupuesto guardado.','See how extra monthly income would change your capacity; this does not change your saved budget.'],
 scenarioExpense:['Prueba el efecto de gastos mensuales adicionales; esta simulación no modifica tus registros.','See the effect of extra monthly expenses; this scenario does not change your records.'],
 methods:['Bola de nieve prioriza la deuda de menor saldo. Avalancha prioriza la tasa más alta comparable. Ambas pagan primero los mínimos y dirigen el excedente a la deuda prioritaria.','Snowball prioritizes the smallest balance. Avalanche prioritizes the highest comparable rate. Both pay minimums first and direct extra funds to the priority debt.'],
 simBudget:['Pago mensual total para todas las deudas de la moneda seleccionada, incluidos los mínimos y cualquier abono adicional.','Total monthly payment for all debts in the selected currency, including minimums and any extra payment.'],
 simDate:['Fecha desde la que empieza la proyección mensual. La fecha de cancelación es una estimación.','Date the monthly projection starts. The payoff date is an estimate.'],
 min:['Pago mínimo mensual exigido por la entidad para esta deuda. Confírmalo en tu estado de cuenta.','The monthly minimum required by the lender for this debt. Confirm it on your statement.'],
 rate:['Tasa anual de interés confirmada para esta deuda, expresada en porcentaje. No introduzcas una tasa mensual aquí.','Confirmed annual interest rate for this debt, entered as a percentage. Do not enter a monthly rate here.'],
 kind:['Selecciona APR si la tasa es nominal anual o E.A. si es efectiva anual. La aplicación las convierte a una tasa mensual comparable.','Select APR for a nominal annual rate or E.A. for an effective annual rate. The app converts each to a comparable monthly rate.'],
 alerts:['Configura fechas y anticipación para ver avisos al abrir la aplicación. Esta versión no garantiza avisos en segundo plano.','Set dates and lead time to see reminders when you open the app. This version does not guarantee background alerts.'],
 cutoff:['Día del mes en que cierra el período de movimientos. Consulta la fecha real en tu estado de cuenta.','Day of the month when the billing period closes. Check the actual date on your statement.'],
 due:['Día límite mensual indicado por tu entidad para recibir el pago. Es diferente de la fecha de corte.','Monthly deadline your lender gives for receiving payment. It differs from the statement closing date.'],
 paid:['Si ya pagaste, indica la fecha hasta la que consideras cumplidos los pagos para evitar avisos anteriores. No realiza ningún pago.','If you have paid, enter the date through which payments are complete to suppress earlier reminders. This does not make a payment.'],
 before:['Número de días de anticipación para el aviso; por ejemplo, 3 muestra un aviso tres días antes.','Number of days before the event to show a reminder; for example, 3 means three days before.'],
 cutoffOn:['Activa o desactiva los recordatorios del corte para esta obligación.','Turn statement closing reminders on or off for this debt.'],
 paymentOn:['Activa o desactiva los recordatorios de vencimiento para esta obligación.','Turn payment due reminders on or off for this debt.'],
 sameDay:['Además del aviso anticipado, incluye un aviso el mismo día del corte o del vencimiento.','In addition to the advance reminder, include one on the closing or due date.']};
const labels={plan:['plan financiero','financial plan'],income:['ingresos','income'],essential:['gastos esenciales','essential expenses'],fixed:['gastos fijos','fixed expenses'],variable:['gastos variables','variable expenses'],minimums:['pagos mínimos','minimum payments'],extra:['abono adicional','extra payment'],scenarioIncome:['ingresos adicionales','extra income'],scenarioExpense:['gastos adicionales','extra expenses'],methods:['métodos de pago','payment strategies'],simBudget:['pago mensual total','total monthly payment'],simDate:['fecha de inicio','start date'],min:['pago mínimo','minimum payment'],rate:['tasa anual','annual rate'],kind:['tipo de tasa','rate type'],alerts:['recordatorios','reminders'],cutoff:['fecha de corte','statement closing date'],due:['fecha de pago','payment due date'],paid:['pagos cumplidos','completed payments'],before:['anticipación del aviso','reminder lead time'],cutoffOn:['avisos de corte','statement reminders'],paymentOn:['avisos de pago','payment reminders'],sameDay:['aviso del día','same-day reminder']};
function localize(help){const key=help.dataset.educationKey,lang=document.documentElement.lang==='en'?1:0;const body=help.querySelector('p'),summary=help.querySelector('summary');if(body.textContent!==definitions[key][lang])body.textContent=definitions[key][lang];const title=(lang?'Information about ':'Información sobre ')+labels[key][lang];if(summary.getAttribute('aria-label')!==title)summary.setAttribute('aria-label',title)}
function attach(anchor,key,position='after'){if(!anchor||!definitions[key]||anchor.dataset.educationHelp===key)return;anchor.dataset.educationHelp=key;const help=document.createElement('details');help.className='education-help';help.dataset.educationKey=key;help.dataset.localizedOutput='true';const summary=document.createElement('summary');summary.textContent='ⓘ';const body=document.createElement('p');help.append(summary,body);if(position==='heading'){const row=document.createElement('div');row.className='education-heading';anchor.before(row);row.append(anchor,help)}else if(position==='field'){const row=document.createElement('div');row.className='education-heading';anchor.before(row);row.append(anchor,help)}else if(position==='reminder'){const row=document.createElement('div');row.className='education-reminder-field';anchor.before(row);row.append(anchor,help)}else anchor.after(help);localize(help)}
function refresh(){
 attach(document.querySelector('#view-plan #nav-plan'),'plan','heading');attach(document.querySelector('#view-methods #plan-financiero h2'),'methods','heading');attach(document.querySelector('#view-alerts section > h2'),'alerts','heading');
 for(const [id,key] of Object.entries({'budget-income':'income','budget-essential':'essential','budget-fixed':'fixed','budget-variable':'variable','budget-minimums':'minimums','budget-extra':'extra','scenario-income':'scenarioIncome','scenario-expense':'scenarioExpense','sim-budget':'simBudget','sim-date':'simDate'}))attach(document.querySelector(`label[for="${id}"]`),key,'field');
 for(const el of document.querySelectorAll('#simulation-rows label[for]')){const prefix=el.getAttribute('for').split('-')[0];if(['min','rate','kind'].includes(prefix))attach(el,prefix,'field')}
 for(const form of document.querySelectorAll('#rem-content form')){const fields=form.querySelectorAll('label.field');['cutoff','due','paid','before'].forEach((key,i)=>attach(fields[i],key,'reminder'));const checks=Array.from(form.querySelectorAll('label')).filter(el=>el.querySelector('input[type="checkbox"]'));['cutoffOn','paymentOn','sameDay'].forEach((key,i)=>attach(checks[i],key,'reminder'))}
 for(const help of document.querySelectorAll('.education-help[data-education-key]'))localize(help)
}
let scheduled=false;const observer=new MutationObserver(()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;refresh()})});const main=document.querySelector('main');if(main)observer.observe(main,{subtree:true,childList:true});document.addEventListener('deudas:languagechange',refresh);refresh();
})();
